function solarizeProcess(data,w,h,opts){
  opts=opts||{};
  var thr=opts.threshold!=null?opts.threshold:128;
  if(thr<0)thr=0; else if(thr>255)thr=255;
  var out=new Uint8ClampedArray(data.length);
  for(var i=0;i<data.length;i+=4){
    var r=data[i], g=data[i+1], b=data[i+2];
    out[i]= r>=thr? 255-r : r;
    out[i+1]= g>=thr? 255-g : g;
    out[i+2]= b>=thr? 255-b : b;
    out[i+3]=data[i+3];
  }
  return out;
}

var EXPORTS={solarizeProcess:solarizeProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SolarizeForgePure = EXPORTS; }
